import{_ as a,c as t,o as s,ae as n}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/troubleshooting.md","filePath":"fr/guide/troubleshooting.md","lastUpdated":1795170900000}'),r={name:"fr/guide/troubleshooting.md"};function i(o,e,l,u,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h1><p>Des solutions aux problèmes les plus courants.</p><h2 id="une-page-ne-s-ouvre-pas" tabindex="-1">Une page ne s&#39;ouvre pas <a class="header-anchor" href="#une-page-ne-s-ouvre-pas" aria-label="Permalink to &quot;Une page ne s&#39;ouvre pas&quot;">​</a></h2><ul><li>Vérifiez que d&#39;autres sites s&#39;ouvrent, puis rechargez avec ⌘R.</li><li>Si un filtre de publicités est actif, mettez-le en pause un instant pour voir s&#39;il bloque le site.</li><li>Essayez une fenêtre privée (⌘⇧N). Si la page s&#39;ouvre là, supprimez les cookies du site depuis les réglages.</li></ul><h2 id="un-telechargement-bloque-ou-reste-incomplet" tabindex="-1">Un téléchargement bloque ou reste incomplet <a class="header-anchor" href="#un-telechargement-bloque-ou-reste-incomplet" aria-label="Permalink to &quot;Un téléchargement bloque ou reste incomplet&quot;">​</a></h2><ul><li>Ouvrez le panneau de téléchargement, mettez l&#39;élément en pause, puis reprenez.</li><li>Si une vidéo enregistrée depuis une page a échoué, supprimez le fichier incomplet et réessayez. Les vidéos fractionnées sont assemblées en un seul MP4 ; en cas d&#39;échec, les morceaux restent dans le dossier de téléchargements.</li></ul><h2 id="les-favoris-ne-se-sont-pas-importes" tabindex="-1">Les favoris ne se sont pas importés <a class="header-anchor" href="#les-favoris-ne-se-sont-pas-importes" aria-label="Permalink to &quot;Les favoris ne se sont pas importés&quot;">​</a></h2><p>Exportez d&#39;abord les favoris de votre ancien navigateur au format HTML. Dans Persim, ouvrez le gestionnaire de favoris et choisissez <strong>Importer HTML</strong>. Dossiers et liens en double sont triés automatiquement.</p><h2 id="aucune-video-detectee" tabindex="-1">Aucune vidéo détectée <a class="header-anchor" href="#aucune-video-detectee" aria-label="Permalink to &quot;Aucune vidéo détectée&quot;">​</a></h2><p>Tous les sites ne proposent pas une vidéo enregistrable. Ouvrez le panneau multimédia sur la page concernée. Si rien n&#39;apparaît, le mode de lecture du site ne permet pas un enregistrement direct.</p><h2 id="l-application-ralentit" tabindex="-1">L&#39;application ralentit <a class="header-anchor" href="#l-application-ralentit" aria-label="Permalink to &quot;L&#39;application ralentit&quot;">​</a></h2><p>Fermez les onglets inutilisés ou désactivez un abonnement de filtrage dont vous n&#39;avez plus besoin. Les autorisations des sites se vérifient dans les réglages.</p><h2 id="toujours-aucun-resultat" tabindex="-1">Toujours aucun résultat <a class="header-anchor" href="#toujours-aucun-resultat" aria-label="Permalink to &quot;Toujours aucun résultat&quot;">​</a></h2><p>Écrivez à <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> en décrivant ce que vous faisiez ; si possible, joignez une capture d&#39;écran.</p>',14)])])}const h=a(r,[["render",i]]);export{m as __pageData,h as default};
